SELECT m.chembl_id AS compound_chembl_id, cs.canonical_smiles FROM molecule_dictionary m JOIN activities act ON m.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary t ON a.tid = t.tid JOIN compound_structures cs ON m.molregno = cs.molregno WHERE t.chembl_id = 'CHEMBL5162' AND a.assay_organism = 'Homo sapiens' ORDER BY m.chembl_id
